// Aetherborne: Warband — application shell, creation wizard, dungeon loop and battle UI.
import {
  RACES,
  CLASSES,
  STAT_KEYS,
  STAT_LABELS,
  STAT_SHORT,
  FLOORS,
  floorData,
  raceById,
  classById,
  representativeKit,
  STATUSES
} from './data.js';
import {
  createCharacter,
  computeCharacter,
  grantXp,
  restoreCharacter,
  randomCharacter,
  randomName,
  xpNeeded
} from './character.js';
import {
  generateDungeon,
  drawDungeon,
  drawMinimap,
  revealAround,
  entityAt,
  isWalkable,
  hashSeed
} from './dungeon.js';
import { Battle } from './battle.js';
import { AudioEngine } from '../audio.js';

const SAVE_KEY = 'aetherborne_warband_v1';
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const clamp = (v, min, max) => Math.max(min, Math.min(max, v));

function esc(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function sanitizeName(value) {
  return String(value || '').replace(/[<>&"']/g, '').replace(/\s+/g, ' ').trim().slice(0, 18);
}

function loadState() {
  const defaults = { version: 1, party: [], run: null, settings: { sound: true, music: true } };
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (!raw) return defaults;
    const parsed = JSON.parse(raw);
    const party = Array.isArray(parsed.party) ? parsed.party.slice(0, 6) : [];
    while (party.length < 6) party.push(null);
    for (let i = 0; i < party.length; i += 1) {
      const member = party[i];
      if (!member || !raceById(member.raceId) || !classById(member.classId)) party[i] = null;
    }
    return {
      version: 1,
      party,
      run: parsed.run && typeof parsed.run.floor === 'number' ? parsed.run : null,
      settings: { ...defaults.settings, ...(parsed.settings || {}) }
    };
  } catch (error) {
    console.warn('Save could not be read', error);
    return defaults;
  }
}

const saved = loadState();

const app = {
  mode: 'title',
  settings: saved.settings,
  party: saved.party,
  run: saved.run,
  audio: new AudioEngine(saved.settings),
  draft: null,
  step: 0,
  editingSlot: null,
  selectedSlot: null,
  manualTab: 'overview',
  overlayOpen: false,
  overlayClosable: true,
  dungeon: null,
  view: { visible: new Set(), explored: new Set(), camX: null, camY: null },
  keys: new Set(),
  touchDir: null,
  lastMove: 0,
  battle: null,
  battleState: null,
  currentEncounter: null,
  battleReturn: 'dungeon',
  lastFrame: 0,
  time: 0,
  toastTimer: null,
  dungeonToastTimer: null
};

function persist() {
  try {
    localStorage.setItem(SAVE_KEY, JSON.stringify({
      version: 1,
      party: app.party,
      run: app.run,
      settings: app.settings,
      updatedAt: Date.now()
    }));
  } catch (error) {
    console.warn('Save failed', error);
  }
}

