  return {
    weapon,
    armor,
    charm,
    damage,
    cooldown: weapon.cooldown / attackSpeed,
    range: weapon.range,
    arc: weapon.arc,
    crit: clamp(weapon.crit + (charm?.effect?.crit || 0) + b('eagleEye') * 0.08, 0, 0.75),
    lifesteal: b('leech') * 0.03,
