}

function openHub(tab = game.hubTab) {
  game.mode = 'hub';
  game.hubTab = tab;
  hideAllScreens();
  showEl(UI.hud, false);
  showEl(UI.hub, true);
  game.audio.resume();
  game.audio.play('ui');
  renderHub();
}

