function drawTelegraph(ctx, e, t) {
  const tele = e.telegraph;
  if (!tele) return;
  const progress = Math.min(1, tele.t / tele.dur);
  const pulse = 0.35 + 0.3 * Math.sin(t * 18);
  ctx.save();
  if (tele.kind === 'arc') {
    ctx.translate(e.x, e.y);
    ctx.rotate(tele.dir);
